package dev.cheeseowl.gmbg;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicInteger;

/** Synthetic receiver/query fixtures; not Android or LSPosed runtime execution. */
public class HistoryTest {
    private final Object receiver=new Object(),intent=new Object(),view=new Object(),context=new Object();
    private HistoryScope.Delivery delivery(String q){return d(1,true,"action_search_history","history_ime_g","web_all","2",true,q);}
    private HistoryScope.Delivery d(int branch,boolean resumed,String action,String source,String tab,String type,boolean search,String q){
        return new HistoryScope.Delivery(receiver,intent,view,context,branch,resumed,action,source,tab,type,search,q);
    }
    private Trace.Frame frame(long id,long parent,Trace.Kind kind){return new Trace.Frame(id,parent,kind);}
    private HistoryScope.Entry enter(HistoryScope s,HistoryScope.Delivery d){return s.enter(d,frame(10,0,Trace.Kind.HISTORY_RECEIVE));}
    private HistoryScope.Claim claim(HistoryScope s,HistoryScope.Delivery d){return s.claim(context,d.query(),d.source(),"",false,frame(11,10,Trace.Kind.QUERY),d);}
    private void decision(EngineChoice choice,FeatureState flags,String raw) throws Exception {
        String query=QueryScope.normalize(raw);DecisionLease lease=new DecisionLease(flags,query,choice.template,new Object(),new Object());
        lease.templated=true;String url=choice.template.replace("{searchTerms}",java.net.URLEncoder.encode(query,"UTF-8"));
        assertTrue(lease.encoded(choice.template,query,url));assertTrue(lease.dispatch(flags,lease.model,lease.item,url,url));
        assertTrue(SearchUrlPolicy.matches(choice,choice.template,query,url));
        assertFalse(SearchUrlPolicy.structure(choice==EngineChoice.BING?EngineChoice.GOOGLE:EngineChoice.BING,url));
    }
    @Test public void verifiedHistoryCanClaimBing() throws Exception {var s=new HistoryScope();var d=delivery("固定 历史 %&#+ 🦉");var e=enter(s,d);assertEquals(HistoryScope.Reason.ACCEPTED,e.reason());var c=claim(s,d);assertNotNull(c.permit());assertTrue(s.live(c.permit(),d));decision(EngineChoice.BING,FeatureState.checked(true,true,true,EngineChoice.BING,1),d.query());s.exit(e.token());assertFalse(s.live(c.permit(),d));}
    @Test public void verifiedHistoryCanClaimGoogle() throws Exception {var s=new HistoryScope();var d=delivery("固定历史");var e=enter(s,d);assertNotNull(claim(s,d).permit());decision(EngineChoice.GOOGLE,FeatureState.checked(true,true,true,EngineChoice.GOOGLE,2),d.query());s.exit(e.token());}
    @Test public void legacyHistoryStillUsesUnchangedAllowlist() throws Exception {assertTrue(QueryScope.allows("history","",false));decision(EngineChoice.BING,FeatureState.checked(true,true,true,EngineChoice.BING,1),"旧历史");assertFalse(QueryScope.allows("history","",true));assertFalse(QueryScope.allows("history","https://example.test",false));}
    @Test public void otherAndImeLabelAloneRemainOutsideGlobalAllowlist(){for(String source:new String[]{"other","history_ime_g","history2","360","douyin","webview",null})assertFalse(QueryScope.allows(source,"",false));assertNull(claim(new HistoryScope(),delivery("固定")).permit());}
    @Test public void exactReceiverVariantAndResumeRequired(){assertEquals(HistoryScope.Reason.WRONG_BRANCH,HistoryScope.qualifies(d(0,true,"action_search_history","history_ime_g","web_all","2",true,"fixed")));assertEquals(HistoryScope.Reason.NOT_RESUMED,HistoryScope.qualifies(d(1,false,"action_search_history","history_ime_g","web_all","2",true,"fixed")));}
    @Test public void wrongActionsIncludingLocalServicesAndAiAreDenied(){for(String a:new String[]{"action_search","native_sug_word_search_instant","action_search_sugg_tab","action_accept_ai","search_quick","search_instant","change_query",null})assertEquals(HistoryScope.Reason.WRONG_ACTION,HistoryScope.qualifies(d(1,true,a,"history_ime_g","web_all","2",true,"fixed")));}
    @Test public void wrongTabsIncludingNewPageAndMultiTabAreDenied(){for(String t:new String[]{"local_all","web_new_page","app","contact","settings","service","web_all_extra","web_all,local_all",null})assertEquals(HistoryScope.Reason.WRONG_TAB,HistoryScope.qualifies(d(1,true,"action_search_history","history_ime_g",t,"2",true,"fixed")));}
    @Test public void onlyExactTypeTwoAndExplicitSearchTrueAreAccepted(){for(String type:new String[]{"1","0","3","02","unknown",null})assertEquals(HistoryScope.Reason.WRONG_TYPE,HistoryScope.qualifies(d(1,true,"action_search_history","history_ime_g","web_all",type,true,"fixed")));assertEquals(HistoryScope.Reason.SEARCH_DISABLED,HistoryScope.qualifies(d(1,true,"action_search_history","history_ime_g","web_all","2",false,"fixed")));}
    @Test public void wrongSourceAndJsonImpersonationDoNotGrantContext(){for(String src:new String[]{"history","other","{\"source\":\"history_ime_g\"}","history_ime_g ","douyin","360",null})assertEquals(HistoryScope.Reason.WRONG_SOURCE,HistoryScope.qualifies(d(1,true,"action_search_history",src,"web_all","2",true,"fixed")));}
    @Test public void historyWebsitesSchemesAndInternalPathsAreNeverQueries(){for(String q:new String[]{"https://example.test/a?q=fixed","http://baidu.com","www.example.test","example.com","example.test/path","127.0.0.1:80","127.0.0.1","[::1]","//example.test","/settings","intent://a","onesearch:fixed","tel:123","content://a","market://a"})assertFalse(q,HistoryScope.text(q));}
    @Test public void emptyMalformedAndOversizedQueriesFail(){for(String q:new String[]{null,"","  ","bad\uD800","bad\uDC00","bad\ntext","a".repeat(8193)})assertFalse(HistoryScope.text(q));}
    @Test public void fixedUnicodePercentAndParametersEncodedOnlyOnce() throws Exception {for(String q:new String[]{"普通词","a b","a%b","a&b","a#b","a+b","中文 🦉","%26","保留 原始 语义"}){assertTrue(HistoryScope.text(q));for(EngineChoice choice:new EngineChoice[]{EngineChoice.BING,EngineChoice.GOOGLE})decision(choice,FeatureState.checked(true,true,true,choice,7),q);}}
    @Test public void directAiWrongContextSourceOrQueryCannotClaim(){for(int bad=0;bad<5;bad++){var s=new HistoryScope();var d=delivery("fixed");enter(s,d);var c=s.claim(bad==0?new Object():context,bad==1?"other":"fixed",bad==2?"other":"history_ime_g",bad==3?"https://example.test":"",bad==4,frame(11,10,Trace.Kind.QUERY),d);assertEquals(HistoryScope.Reason.WRONG_ARGS,c.reason());assertNull(c.permit());}}
    @Test public void zeroParentAndUnexpectedNestedQueryDoNotProveHistory(){for(long p:new long[]{0,99}){var s=new HistoryScope();var d=delivery("fixed");enter(s,d);assertEquals(HistoryScope.Reason.WRONG_PARENT,s.claim(context,"fixed","history_ime_g","",false,frame(11,p,Trace.Kind.QUERY),d).reason());}}
    @Test public void changingIntentOrQueryInvalidatesPermit(){var s=new HistoryScope();var d=delivery("fixed");enter(s,d);assertEquals(HistoryScope.Reason.STALE,claim(s,delivery("changed")).reason());assertNull(claim(s,d).permit());}
    @Test public void freshIdentityMustBeExactlySame(){var s=new HistoryScope();var d=delivery("fixed");enter(s,d);var other=new HistoryScope.Delivery(receiver,new Object(),view,context,1,true,d.action(),d.source(),d.tab(),d.type(),true,d.query());assertEquals(HistoryScope.Reason.STALE,claim(s,other).reason());}
    @Test public void dispatchRechecksDomainAndMetadata(){var s=new HistoryScope();var d=delivery("fixed");var e=enter(s,d);var c=claim(s,d);assertTrue(s.live(c.permit(),d));assertFalse(s.live(c.permit(),delivery("changed")));assertFalse(s.live(c.permit(),null));s.exit(e.token());assertFalse(s.live(c.permit(),d));}
    @Test public void onlyOneAttemptPerDelivery(){var s=new HistoryScope();var d=delivery("fixed");enter(s,d);assertNotNull(claim(s,d).permit());assertEquals(HistoryScope.Reason.USED,claim(s,d).reason());}
    @Test public void nestedDeliveryInvalidatesOuterEvenAfterChildExit(){var s=new HistoryScope();var d=delivery("fixed");var a=enter(s,d);var c=claim(s,d);var b=s.enter(d,frame(12,11,Trace.Kind.HISTORY_RECEIVE));assertEquals(HistoryScope.Reason.NESTED,b.reason());s.exit(b.token());assertFalse(s.live(c.permit(),d));s.exit(a.token());assertNull(s.delivery());}
    @Test public void crossThreadCannotInheritReceiver() throws Exception {var s=new HistoryScope();var d=delivery("fixed");var e=enter(s,d);AtomicReference<HistoryScope.Claim> other=new AtomicReference<>();Thread t=new Thread(()->other.set(claim(s,d)));t.start();t.join();assertNull(other.get().permit());assertNotNull(claim(s,d).permit());s.exit(e.token());}
    @Test public void asynchronousWorkAfterReceiverCannotClaim(){var s=new HistoryScope();var d=delivery("fixed");var e=enter(s,d);s.exit(e.token());assertNull(claim(s,d).permit());assertNull(s.delivery());}
    @Test public void exceptionPropagatesOnceAndFinallyCleans(){var s=new HistoryScope();var d=delivery("fixed");Error expected=new Error("fixture");AtomicInteger originals=new AtomicInteger();try{var e=enter(s,d);try{originals.incrementAndGet();throw expected;}finally{s.exit(e.token());}}catch(Error actual){assertSame(expected,actual);}assertEquals(1,originals.get());assertNull(s.delivery());assertNull(claim(s,d).permit());}
    @Test public void independentClicksDoNotLeakContext(){var s=new HistoryScope();for(String q:new String[]{"first","second"}){var d=delivery(q);var e=enter(s,d);assertNotNull(claim(s,d).permit());s.exit(e.token());assertNull(s.delivery());}}
    @Test public void fourSwitchCombinationsKeepRoutingIndependent() throws Throwable {for(boolean engine:new boolean[]{false,true})for(boolean browser:new boolean[]{false,true})for(EngineChoice choice:new EngineChoice[]{EngineChoice.BING,EngineChoice.GOOGLE}){var f=FeatureState.checked(engine,browser,true,choice,1);assertEquals(engine,f.engine());if(engine)decision(choice,f,"固定 %&");else assertFalse(FeatureState.checked(true,browser,true,choice,1).sameDecision(f));AtomicInteger redirect=new AtomicInteger(),original=new AtomicInteger();new BrowserDispatcher().run(browser,()->redirect.incrementAndGet(),()->{original.incrementAndGet();return null;},outcome->{});assertEquals(browser?1:0,redirect.get());assertEquals(browser?0:1,original.get());}}
    @Test public void configRaceUnreadableOrChangedModelRejectsFinalDecision(){var f=FeatureState.checked(true,true,true,EngineChoice.BING,1);var d=new DecisionLease(f,"fixed",EngineChoice.BING.template,new Object(),new Object());d.templated=true;String url=SearchUrlPolicy.expected(d.template,d.query);assertTrue(d.encoded(d.template,d.query,url));for(var changed:new FeatureState[]{FeatureState.unavailable(),FeatureState.checked(false,true,true,EngineChoice.BING,2),FeatureState.checked(true,true,true,EngineChoice.GOOGLE,2)})assertFalse(d.dispatch(changed,d.model,d.item,url,url));assertFalse(d.dispatch(f,new Object(),d.item,url,url));assertFalse(d.dispatch(f,d.model,new Object(),url,url));}
    @Test public void previousSuccessfulEntrypointsAndVersionGateRemain(){for(String source:new String[]{"history","right_search_btn","keyboard_search_btn","searchengine_click"})assertTrue(QueryScope.allows(source,"",false));assertFalse(QueryScope.allows("sug_page","",false));assertFalse(TargetSpec.knownVersion("unknown",TargetSpec.CODE));assertTrue(TargetSpec.knownVersion(TargetSpec.VERSION,TargetSpec.CODE));}
    @Test public void historyDiagnosticsContainOnlyEnumsAndQueryAssociation(){StringBuilder b=new StringBuilder();DiagnosticLog log=new DiagnosticLog(b::append);log.emit(DiagnosticLog.Event.HISTORY_SCOPE,DiagnosticLog.Hook.QUERY,DiagnosticLog.Phase.STATUS,frame(11,10,Trace.Kind.QUERY),HistoryScope.Reason.ACCEPTED,HistoryScope.Source.IME_HISTORY);String text=b.toString();assertTrue(text.contains("call=11 parent=10"));assertTrue(text.contains("ACCEPTED"));assertTrue(text.contains("IME_HISTORY"));assertFalse(text.contains("history_ime_g"));assertFalse(text.contains("fixed"));}
}
